# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BİLÂD-I ŞAM COĞRAFYASI VE ŞAM ŞEHRİNİN TARİHÎ-DİNÎ ÖNEMİ</text>\n  <rect x="20" y="44" width="210" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">1. Coğrafi Kapsam (Bilâd-ı Şam)</text>\n  <rect x="34" y="78" width="182" height="32" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="125" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Dımaşk · Kudüs · Busrâ · Gazze</text>\n  <text x="32" y="128" font-size="10" fill="#334155">• Suriye, Filistin, Ürdün ve</text>\n  <text x="40" y="143" font-size="10" fill="#334155">Lübnan topraklarını kapsar.</text>\n  <text x="32" y="165" font-size="10" fill="#334155">• Bereketli Hilal\'in Akdeniz\'e</text>\n  <text x="40" y="180" font-size="10" fill="#334155">açılan verimli kuşağıdır.</text>\n  <text x="32" y="202" font-size="10" fill="#334155">• Hicaz, Mısır ve Anadolu</text>\n  <text x="40" y="217" font-size="10" fill="#334155">arasındaki stratejik köprüdür.</text>\n\n  <rect x="245" y="44" width="210" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">2. Dinî ve Manevi Değeri</text>\n  <rect x="259" y="78" width="182" height="32" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Mübarek Kılınan Topraklar</text>\n  <text x="257" y="128" font-size="10" fill="#334155">• Hz. İbrahim, Hz. İshak, Hz. Yakub</text>\n  <text x="265" y="143" font-size="10" fill="#334155">ve Hz. İsa gibi peygamberlerin</text>\n  <text x="265" y="158" font-size="10" fill="#334155">tebliğ coğrafyasıdır.</text>\n  <text x="257" y="180" font-size="10" fill="#334155">• İsrâ 1. ayette çevresi mübarek</text>\n  <text x="265" y="195" font-size="10" fill="#334155">kılınan Mescid-i Aksâ buradadır.</text>\n  <text x="257" y="217" font-size="10" font-weight="bold" fill="#92400e">• Nebevî Bereket Duası: "Şam\'ımızı</text>\n  <text x="265" y="230" font-size="9.5" font-weight="bold" fill="#92400e">ve Yemen\'imizi mübarek kıl!"</text>\n\n  <rect x="470" y="44" width="210" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">3. Kureyş\'in Yaz Ticareti</text>\n  <rect x="484" y="78" width="182" height="32" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="575" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Îlâf Antlaşmaları ve Kervanlar</text>\n  <text x="482" y="128" font-size="10" fill="#334155">• Kureyş suresinde anılan yaz</text>\n  <text x="490" y="143" font-size="10" fill="#334155">yolculukları Şam\'a yapılırdı.</text>\n  <text x="482" y="165" font-size="10" fill="#334155">• Hz. Peygamber\'in dedesi Hâşim,</text>\n  <text x="490" y="180" font-size="10" fill="#334155">Bizans ile ticaret izni almıştır.</text>\n  <text x="482" y="202" font-size="10" fill="#334155">• Busrâ ve Gazze panayırları</text>\n  <text x="490" y="217" font-size="10" fill="#334155">başlıca ticaret merkezleriydi.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PEYGAMBERİMİZİN GENÇLİĞİNDE ŞAM (BUSRÂ) TİCARET YOLCULUKLARI</text>\n  <rect x="20" y="44" width="320" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">1. Birinci Şam Yolculuğu (9-12 Yaş)</text>\n  <rect x="34" y="78" width="292" height="32" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Amcası Ebû Tâlib ile Busrâ Seferi</text>\n  <text x="34" y="128" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Dönem:</tspan> Dedesi Abdülmuttalib\'in vefatından</text>\n  <text x="42" y="143" font-size="10" fill="#475569">sonra amcası Ebû Tâlib\'in himayesindeyken.</text>\n  <text x="34" y="165" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Durak:</tspan> Şam bölgesinin önemli ticaret</text>\n  <text x="42" y="180" font-size="10" fill="#475569">kavşağı olan Busrâ kasabası.</text>\n  <text x="34" y="202" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Önemli Olay:</tspan> Rahip Bahîrâ\'nın nübüvvet</text>\n  <text x="42" y="217" font-size="10" fill="#475569">işaretlerini görerek Ebû Tâlib\'i uyarması.</text>\n\n  <rect x="360" y="44" width="320" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. İkinci Şam Yolculuğu (25 Yaş)</text>\n  <rect x="374" y="78" width="292" height="32" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Hz. Hatice\'nin Kervanı ve Meysere</text>\n  <text x="374" y="128" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Görevi:</tspan> Muhammedü\'l-Emîn vasfıyla</text>\n  <text x="382" y="143" font-size="10" fill="#475569">Hz. Hatice\'nin kervanını Busrâ\'ya götürmesi.</text>\n  <text x="374" y="165" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Yol Arkadaşı:</tspan> Hz. Hatice\'nin yardımcısı</text>\n  <text x="382" y="180" font-size="10" fill="#475569">Meysere\'nin onun dürüstlüğüne şahitliği.</text>\n  <text x="374" y="202" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Sonucu:</tspan> Bereketli kazanç ve Hz. Hatice</text>\n  <text x="382" y="217" font-size="10" fill="#475569">ile gerçekleşen mutlu evlilik.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">NÜBÜVVET DÖNEMİNDEN FETİH SÜRECİNE ŞAM KRONOLOJİSİ</text>\n  <rect x="20" y="44" width="155" height="194" rx="8" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="97" y="65" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#5b21b6">1. Davet Mektubu (628)</text>\n  <text x="28" y="90" font-size="10" fill="#334155">• <tspan font-weight="bold">Elçi:</tspan> Dıhye b. Halîfe</text>\n  <text x="28" y="112" font-size="10" fill="#334155">• <tspan font-weight="bold">Muhatap:</tspan> Bizans</text>\n  <text x="34" y="126" font-size="9.5" fill="#334155">İmparatoru Herakleios</text>\n  <text x="28" y="148" font-size="10" fill="#334155">• Şam\'da Ebû Süfyân</text>\n  <text x="34" y="162" font-size="9.5" fill="#334155">ile yapılan mülakat</text>\n  <text x="34" y="176" font-size="9.5" fill="#334155">sonucu hakikatin</text>\n  <text x="34" y="190" font-size="9.5" fill="#334155">onaylanması.</text>\n\n  <rect x="188" y="44" width="155" height="194" rx="8" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="265" y="65" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">2. Mûte Seferi (629)</text>\n  <text x="196" y="90" font-size="10" fill="#334155">• <tspan font-weight="bold">Sebep:</tspan> Elçi Hâris b.</text>\n  <text x="202" y="104" font-size="9.5" fill="#334155">Umeyr\'in Busrâ\'da</text>\n  <text x="202" y="118" font-size="9.5" fill="#334155">şehit edilmesi.</text>\n  <text x="196" y="140" font-size="10" fill="#334155">• <tspan font-weight="bold">Komutanlar:</tspan> Zeyd,</text>\n  <text x="202" y="154" font-size="9.5" fill="#334155">Ca\'fer ve Abdullah b.</text>\n  <text x="202" y="168" font-size="9.5" fill="#334155">Revâha\'nın şehadeti;</text>\n  <text x="202" y="182" font-size="9.5" font-weight="bold" fill="#991b1b">Hâlid b. Velîd\'in</text>\n  <text x="202" y="196" font-size="9.5" fill="#334155">başarılı manevrası.</text>\n\n  <rect x="356" y="44" width="155" height="194" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="433" y="65" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">3. Tebük ve Üsâme (630-632)</text>\n  <text x="364" y="90" font-size="10" fill="#334155">• <tspan font-weight="bold">Tebük (630):</tspan> Hz.</text>\n  <text x="370" y="104" font-size="9.5" fill="#334155">Peygamber\'in Şam</text>\n  <text x="370" y="118" font-size="9.5" fill="#334155">yönüne son gazvesi.</text>\n  <text x="364" y="142" font-size="10" fill="#334155">• <tspan font-weight="bold">Üsâme Ordusu (632):</tspan></text>\n  <text x="370" y="156" font-size="9.5" fill="#334155">Vefat öncesi hazırlanan</text>\n  <text x="370" y="170" font-size="9.5" fill="#334155">ve Hz. Ebû Bekir\'in</text>\n  <text x="370" y="184" font-size="9.5" fill="#334155">Şam sınırına yolladığı</text>\n  <text x="370" y="198" font-size="9.5" fill="#334155">sancak ordusu.</text>\n\n  <rect x="524" y="44" width="156" height="194" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="602" y="65" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">4. Şam\'ın Fethi (635)</text>\n  <text x="532" y="90" font-size="10" fill="#334155">• <tspan font-weight="bold">Halife:</tspan> Hz. Ebû Bekir</text>\n  <text x="538" y="104" font-size="9.5" fill="#334155">başlattı, Hz. Ömer</text>\n  <text x="538" y="118" font-size="9.5" fill="#334155">döneminde tamamlandı.</text>\n  <text x="532" y="140" font-size="10" fill="#334155">• <tspan font-weight="bold">Komutanlar:</tspan> Ebû</text>\n  <text x="538" y="154" font-size="9.5" fill="#334155">Ubeyde b. Cerrâh ve</text>\n  <text x="538" y="168" font-size="9.5" fill="#334155">Hâlid b. Velîd.</text>\n  <text x="532" y="190" font-size="10" font-weight="bold" fill="#15803d">• Ecnâdeyn ve Yermük</text>\n  <text x="538" y="204" font-size="9.5" fill="#334155">zaferleriyle İslamlaşma.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
